'use strict';
/* test-collision.js — 251,505 turned up twice, and it was a coincidence.
 *
 * The same six-digit number was measured on both sides of this repository: as the
 * size of a monoid generated by positionwise operations plus one translation, and
 * as the count of operand pairs on which the decoded adder takes its full
 * thirteen passes. The larger number collided too — the arbitrary-carry monoid
 * closes at 531,441, which is also the number of operand pairs — so both terms of
 * a ratio matched, at 115/243 on each side.
 *
 * It is an accident, and this pins why. The pairing that produces it is monoid
 * width w against an adder of 3w trits. Evaluate that anywhere other than w = 2
 * and it collapses immediately: at width 1 the monoid acts on three points, so
 * EVERY monoid there has at most 27 elements, while the three-trit adder has 729
 * pairs of which 621 settle late. The monoid universe is smaller than the number
 * it would have to match.
 *
 * COST: about twenty seconds, nearly all of it closing two width-2 monoids. They
 * are the decisive numbers, so they are recomputed here rather than pinned.
 *
 * The two families also grow at rates that are not close — one by a factor of
 * about 7.37 per step, irrationally; the other by about 9,315 across the only two
 * widths where both are computable.
 */

const fs = require('fs');
const path = require('path');
const L = require('../tools/monoid-lib.js');
const T = require('../src/ternary.js');

let pass = 0; const fails = [];
const check = (name, cond, detail = '') => {
  if (cond) { pass++; console.log(`  [PASS] ${name}`); }
  else { fails.push(name); console.log(`  [FAIL] ${name}  ${detail}`); }
};

const carry = x => T.shiftRight(x, 1);
const STATES = [-1, 0, 1];
const MATRIX = STATES.map(c => {
  const row = { '-1': 0, 0: 0, 1: 0 };
  for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
    const s = a + b;
    if (c !== 0 && carry(s + c) === carry(s)) continue;
    row[carry(s + c)] += 1;
  }
  return STATES.map(x => row[x]);
});
const V0 = STATES.map(t => {
  let k = 0;
  for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) if (carry(a + b) === t) k++;
  return k;
});
const stepV = v => STATES.map((_, j) => v.reduce((acc, x, i) => acc + x * MATRIX[i][j], 0));
const sumV = v => v.reduce((x, y) => x + y, 0);
const lateCount = n => { let v = V0; for (let k = 0; k < n - 2; k++) v = stepV(v); return 9 * sumV(v); };
const pairs = n => Math.pow(9, n);

// Memoised: the width-2 closures take seconds each and are asked for repeatedly.
const REACH = new Map();
const reachOf = (w, kind) => {
  const key = `${w}:${kind}`;
  if (!REACH.has(key)) {
    const A = L.arena(w);
    const gens = kind === 'any'
      ? L.topSinglePos(A).concat(L.topcSample(A, 40))
      : L.topSinglePos(A).concat([L.addTable(A, 1)]);
    REACH.set(key, L.audit(gens, A.N, 100, 1200000));
  }
  return REACH.get(key);
};

console.log('\n=== 1. BOTH NUMBERS ARE REAL BEFORE THEY ARE INTERESTING ===');
{
  const one2 = reachOf(2, 'one'), any2 = reachOf(2, 'any');
  check('the 251,505 monoid is CLOSED — saturated, not capped, not depth-exhausted',
    one2.total === 251505 && one2.saturated && !one2.capped && !one2.exhausted,
    JSON.stringify({ t: one2.total, s: one2.saturated, c: one2.capped }));
  check('the 531,441 monoid is closed too, and is not its own cap',
    any2.total === 531441 && any2.saturated && !any2.capped);
  check('and the ratio really is 115/243 on both sides', (() => {
    const g = (a, b) => (b ? g(b, a % b) : a);
    const d1 = g(one2.total, any2.total);
    const d2 = g(lateCount(6), pairs(6));
    return one2.total / d1 === 115 && any2.total / d1 === 243
      && lateCount(6) / d2 === 115 && pairs(6) / d2 === 243;
  })());
}

console.log('\n=== 2. G1 — THE PAIRING DIES AT THE FIRST OTHER PARAMETER ===');
{
  const one1 = reachOf(1, 'one'), any1 = reachOf(1, 'any');
  check('G1 — at width 1 both vocabularies reach 27, the whole function space on three points',
    one1.total === 27 && any1.total === 27 && Math.pow(3, 3) === 27,
    `${one1.total} / ${any1.total}`);
  check('G1 — while the three-trit adder gives 729 pairs and 621 settling late',
    pairs(3) === 729 && lateCount(3) === 621);
  check('G1 — so the monoid UNIVERSE is smaller than the number it would have to match',
    Math.pow(3, 3) < lateCount(3));
  check('   which is as decisive as a refutation gets: not the wrong value, no room for one',
    27 < 621 && 27 < 729);
}

console.log('\n=== 3. G2 — THE TWO FAMILIES GROW AT INCOMPATIBLE RATES ===');
{
  const counts = [];
  for (let n = 2; n <= 12; n++) counts.push(lateCount(n));
  check('G2 — the adder counts obey s(k+1) = 9s(k) − 12s(k−1) at every step to width 12',
    counts.every((c, i) => i < 2 || c === 9 * counts[i - 1] - 12 * counts[i - 2]));
  check('G2 — with dominant root (9 + √33)/2, an irrational 7.3723', (() => {
    const root = (9 + Math.sqrt(33)) / 2;
    const ratio = counts[counts.length - 1] / counts[counts.length - 2];
    return Math.abs(ratio - root) < 1e-5 && Math.abs(root - 7.372281) < 1e-5;
  })());
  check('G2 — the monoid grows by ~9,315 across the same span, over 1,000× faster', (() => {
    const m1 = reachOf(1, 'one').total, m2 = reachOf(2, 'one').total;
    const root = (9 + Math.sqrt(33)) / 2;
    return m2 / m1 > 9000 && (m2 / m1) / root > 1000;
  })());
  check('G2 — and across eleven adder counts and every recorded monoid reach, one value coincides',
    (() => {
      const M = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'FINDINGS.json'), 'utf8'));
      const reaches = new Set();
      for (const s of M.prediction_sets) for (const p of s.predictions) {
        for (const [k, v] of Object.entries(p.measured || {})) {
          if (/^(reach_w\d|ceiling|reach_any_width)$/.test(k)) reaches.add(v);
        }
      }
      const hits = counts.filter(c => reaches.has(c));
      return hits.length === 1 && hits[0] === 251505;
    })());
}

console.log('\n=== 4. G3 — ONE CROSSING, NOT A PATTERN ===');
{
  check('G3 — at width 1 the two denominators are 3^3 and 3^6, and differ',
    reachOf(1, 'any').total === Math.pow(3, 3) && pairs(3) === Math.pow(3, 6)
    && reachOf(1, 'any').total !== pairs(3));
  check('G3 — at width 2 both are 3^12, and collide',
    reachOf(2, 'any').total === Math.pow(3, 12) && pairs(6) === Math.pow(3, 12));
  check('   so the collision is where two different exponent sequences cross, once',
    Math.pow(3, 3) !== Math.pow(3, 6) && Math.pow(3, 12) === Math.pow(3, 12));
  check('   and no formula for the monoid ceiling is claimed — two points do not fix one',
    /No formula is claimed/.test(
      fs.readFileSync(path.join(__dirname, '..', 'tools', 'collision-audit.js'), 'utf8')));
}

console.log('\n=== 5. G4 — HOW RARE IS A COLLISION HERE AT ALL ===');
{
  const M = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'FINDINGS.json'), 'utf8'));
  // Which half a set belongs to is derived from what its tool imports, not
  // hardcoded — the vocabulary work is built on monoid-lib, the circuit work on
  // device.js. The first version of this counted a quantity restated in a second
  // set as a collision with itself, and reported four.
  const half = st => {
    const src = fs.readFileSync(path.join(__dirname, '..', st.tool), 'utf8');
    if (/require\([^)]*monoid-lib/.test(src)) return 'vocabulary';
    if (/require\([^)]*device\.js/.test(src)) return 'circuit';
    return 'other';
  };
  // A census of the manifest must not count the set that IS the census. Recording
  // G4's result put 279,936 and 4,489 into the manifest a second time -- as the
  // values G4 had just EXCLUDED -- and on the next run they looked like
  // collisions. The measurement became part of the corpus it measures. Excluded
  // by matching the censusing tool, not by hardcoding an id.
  const CENSUS = 'collision-audit.js';
  const sets = M.prediction_sets.filter(st => !st.tool.endsWith(CENSUS));
  const sides = new Map(sets.map(st => [st.id, half(st)]));
  const where = new Map();
  for (const st of sets) for (const p of st.predictions) {
    const ints = [...JSON.stringify(p.measured || {}).matchAll(/(\d{4,})/g)].map(x => Number(x[1]));
    for (const v of new Set(ints)) {
      if (!where.has(v)) where.set(v, new Set());
      where.get(v).add(st.id);
    }
  }
  const repeated = [...where.entries()].filter(([v, ids]) => v >= 1000 && ids.size >= 2);
  const crossing = repeated.filter(([, ids]) => new Set([...ids].map(i => sides.get(i))).size >= 2);

  check('G4 — both halves are populated, so the crossing test is not vacuous',
    [...sides.values()].includes('vocabulary') && [...sides.values()].includes('circuit'));
  check(`G4 — exactly two integers ≥ 1000 cross the halves: 251,505 and 531,441`,
    crossing.length === 2 && crossing.map(([v]) => v).sort((a, b) => a - b).join() === '251505,531441',
    crossing.map(([v]) => v).join(' '));
  check('G4 — the other repeats are restatements, and stay inside one half', (() => {
    const inside = repeated.filter(([, ids]) => new Set([...ids].map(i => sides.get(i))).size === 1);
    return inside.length > 0
      && inside.every(([, ids]) => new Set([...ids].map(i => sides.get(i))).size === 1);
  })());
  check('   so a six-digit collision across the halves is rare here — which is why it looked like something',
    crossing.length < repeated.length);
}

console.log('\n=== 6. THE COLLISION DETECTOR HAS TEETH ===');
{
  // A detector that can only ever say "two" proves nothing. Plant a number in a
  // set on each side and confirm it is found; plant one twice on the same side
  // and confirm it is not.
  const sides = new Map([['A', 'vocabulary'], ['B', 'circuit'], ['C', 'circuit']]);
  const crossings = pairsOfSets => {
    const halves = new Set(pairsOfSets.map(i => sides.get(i)));
    return halves.size >= 2;
  };
  check('a value in one set from each half counts as a crossing', crossings(['A', 'B']));
  check('a value in two sets from the SAME half does not', !crossings(['B', 'C']));
  check('and a value in only one set never does', !crossings(['A']));
  check('the classifier reads imports, and really does split the two real tool families', (() => {
    // Not a tautology about this file: run the actual classifier over two real
    // tools and require it to put them on opposite sides.
    const classify = tool => {
      const src = fs.readFileSync(path.join(__dirname, '..', tool), 'utf8');
      if (/require\([^)]*monoid-lib/.test(src)) return 'vocabulary';
      if (/require\([^)]*device\.js/.test(src)) return 'circuit';
      return 'other';
    };
    return classify('tools/monoid-audit.js') === 'vocabulary'
      && classify('tools/adder-audit.js') === 'circuit';
  })());
}

console.log('\n' + '='.repeat(64));
console.log(fails.length ? `FAILED (${fails.length}): ${fails.join(', ')}` : `ALL ${pass} CHECKS PASSED`);
console.log('='.repeat(64));
process.exit(fails.length ? 1 : 0);
